CREATE FUNCTION pg_temp.reject_authority_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Synthetic downstream failure' USING ERRCODE='P0991'; END $$;
CREATE TRIGGER authority_contract_failure BEFORE INSERT ON public."HomeAuditLog"
  FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_authority_audit();
SET LOCAL ROLE service_role;
DO $$
DECLARE h uuid:='dda00000-0000-4000-8000-000000000100'; owner_id uuid:='dda00000-0000-4000-8000-000000000001';
  target uuid:='dda00000-0000-4000-8000-000000000003'; action text; payload jsonb; before_row jsonb; before_overrides jsonb;
BEGIN
  SELECT to_jsonb(o) INTO before_row FROM public."HomeOccupancy" o WHERE home_id=h AND user_id=target;
  SELECT jsonb_agg(to_jsonb(o) ORDER BY permission) INTO before_overrides FROM public."HomePermissionOverride" o WHERE home_id=h AND user_id=target;
  FOREACH action IN ARRAY ARRAY['role','override','remove'] LOOP
    payload:=CASE action WHEN 'role' THEN '{"preset_key":"authority-fixture-member"}' WHEN 'override' THEN '{"permission":"finance.manage","allowed":true}' ELSE '{}' END::jsonb;
    BEGIN
      PERFORM public.mutate_home_member(h,owner_id,target,action,payload);
      RAISE EXCEPTION 'Mutation reported success despite injected audit failure';
    EXCEPTION WHEN SQLSTATE 'P0991' THEN NULL; END;
    IF (SELECT to_jsonb(o) FROM public."HomeOccupancy" o WHERE home_id=h AND user_id=target) IS DISTINCT FROM before_row
      OR (SELECT jsonb_agg(to_jsonb(o) ORDER BY permission) FROM public."HomePermissionOverride" o WHERE home_id=h AND user_id=target) IS DISTINCT FROM before_overrides
      OR EXISTS(SELECT FROM public."HomeScopedGrant" WHERE home_id=h AND grantee_user_id=target AND end_at IS NOT NULL)
      OR EXISTS(SELECT FROM public."ResidencyLetter" WHERE home_id=h AND user_id=target AND status<>'issued') THEN
      RAISE EXCEPTION 'Partial authority state survived failed % transaction',action;
    END IF;
  END LOOP;
  INSERT INTO public."HomeOwner"(home_id,subject_id,owner_status,is_primary_owner) VALUES(h,owner_id,'revoked',true);
  BEGIN
    PERFORM public.mutate_home_member(h,owner_id,owner_id,'remove');
    RAISE EXCEPTION 'Stale-pointer move-out ignored synthetic audit failure';
  EXCEPTION WHEN SQLSTATE 'P0991' THEN NULL; END;
  IF NOT EXISTS(SELECT FROM public."Home" home_row WHERE home_row.id=h AND home_row.owner_id='dda00000-0000-4000-8000-000000000001'::uuid)
    OR NOT EXISTS(SELECT FROM public."HomeOccupancy" WHERE home_id=h AND user_id=owner_id AND is_active AND verification_status='verified') THEN
    RAISE EXCEPTION 'Stale-pointer move-out failed without restoring pointer and membership';
  END IF;
  DELETE FROM public."HomeOwner" WHERE home_id=h AND subject_id=owner_id;
END $$;
RESET ROLE;
DROP TRIGGER authority_contract_failure ON public."HomeAuditLog";
SET LOCAL ROLE service_role;
DO $$
DECLARE h uuid:='dda00000-0000-4000-8000-000000000100'; owner_id uuid:='dda00000-0000-4000-8000-000000000001';
  target uuid:='dda00000-0000-4000-8000-000000000003';
BEGIN
  PERFORM pg_temp.expect_authority(public.mutate_home_member(h,owner_id,target,'remove'),'MEMBER_UPDATED');
  IF EXISTS(SELECT FROM public."HomeOccupancy" WHERE home_id=h AND user_id=target AND (is_active OR verification_status<>'inactive' OR end_at>clock_timestamp()))
    OR EXISTS(SELECT FROM public."HomePermissionOverride" WHERE home_id=h AND user_id=target)
    OR EXISTS(SELECT FROM public."HomeScopedGrant" WHERE home_id=h AND grantee_user_id=target AND (end_at IS NULL OR end_at>clock_timestamp()))
    OR EXISTS(SELECT FROM public."ResidencyLetter" WHERE home_id=h AND user_id=target AND status<>'revoked') THEN
    RAISE EXCEPTION 'Removal left active membership, overrides, grants or letters';
  END IF;
  PERFORM pg_temp.expect_authority(public.mutate_home_member(h,target,target,'remove'),'MEMBER_UPDATED');
  IF NOT EXISTS(SELECT FROM public."HomeOccupancy" WHERE home_id=h AND user_id=target AND verification_status='moved_out') THEN
    RAISE EXCEPTION 'Own inactive occupancy could not complete move-out';
  END IF;
  UPDATE public."HomeOccupancy" SET role_base=NULL,role=NULL,is_active=true,verification_status='unknown' WHERE home_id=h AND user_id=target;
  PERFORM pg_temp.expect_authority(public.mutate_home_member(h,target,target,'remove'),'MEMBER_UPDATED');
  IF EXISTS(SELECT FROM public."HomeOccupancy" WHERE home_id=h AND user_id=target AND (is_active OR verification_status<>'moved_out')) THEN
    RAISE EXCEPTION 'Exact user could not leave their malformed legacy occupancy';
  END IF;
END $$;
RESET ROLE;

-- A proven stale legacy pointer is not an obligation to transfer revoked
-- ownership. Its exact subject may leave; pointer and membership clear together.
-- The no-history and current-verified-primary transfer guards were tested above.
SET LOCAL ROLE service_role;
DO $$
DECLARE h uuid:='dda00000-0000-4000-8000-000000000100'; owner_id uuid:='dda00000-0000-4000-8000-000000000001'; state text;
BEGIN
  FOREACH state IN ARRAY ARRAY['revoked','disputed'] LOOP
    INSERT INTO public."HomeOwner"(home_id,subject_id,owner_status,is_primary_owner) VALUES(h,owner_id,state::public.owner_status_type,true);
    PERFORM pg_temp.expect_authority(public.mutate_home_member(h,owner_id,owner_id,'remove'),'MEMBER_UPDATED');
    IF EXISTS(SELECT FROM public."Home" home_row WHERE home_row.id=h AND home_row.owner_id IS NOT NULL)
      OR EXISTS(SELECT FROM public."HomeOccupancy" WHERE home_id=h AND user_id=owner_id AND (is_active OR verification_status<>'moved_out')) THEN
      RAISE EXCEPTION 'Proven stale owner pointer prevented exact selfleave or survived it';
    END IF;
    DELETE FROM public."HomeOwner" WHERE home_id=h AND subject_id=owner_id;
    UPDATE public."Home" SET owner_id='dda00000-0000-4000-8000-000000000001' WHERE id=h;
    UPDATE public."HomeOccupancy" SET is_active=true,verification_status='verified',end_at=now()+interval '1 day' WHERE home_id=h AND user_id=owner_id;
  END LOOP;
END $$;
RESET ROLE;

