      IF has_table_privilege(current_user,format('public.%I',tab),operation) THEN RAISE EXCEPTION 'Direct % remains on %',operation,tab; END IF;
    END LOOP;
    BEGIN EXECUTE format('DELETE FROM public.%I WHERE false',tab);
      RAISE EXCEPTION 'Direct authenticated deletion succeeded on %',tab;
    EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  END LOOP;
  BEGIN UPDATE public."Home" SET owner_id='dda00000-0000-4000-8000-000000000002' WHERE id='dda00000-0000-4000-8000-000000000100';
    RAISE EXCEPTION 'Direct Home owner pointer mutation succeeded';
  EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  BEGIN PERFORM public.apply_home_role_preset('dda00000-0000-4000-8000-000000000100','dda00000-0000-4000-8000-000000000003','authority-fixture-owner');
    RAISE EXCEPTION 'Legacy preset RPC bypassed authority boundary';
